// === Tab: mySketch ===
/////////////////////////////////////////////////////////////////////////////////////
///                              GlowWorms                                        ///
/////////////////////////////////////////////////////////////////////////////////////
/// let and drag to spawn a bunch of particles with a random directional        ///
/// velocity and colours them based on their x, y velocity.                       ///
///                                                                               ///
/// let by function Carney(5th 2018)                                      ///
///     [matthewcarney64@gmail.com] [https://github.com/Killeroo]                 ///
/////////////////////////////////////////////////////////////////////////////////////

import java.util.Iterator;

let GRAVITY = -0.1;
let MOTION_BLUR = true;

let system = new ParticleSystem();

function setup() {
createCanvas(windowWidth, windowHeight, WEBGL);
}
function draw()
{
  drawBackground();

  system.update();
}

function mouseMoved()
{ 
  system.particles.add(new Particle(new PVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))))));
	system.particles.add(new Particle(new PVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))))));
	system.particles.add(new Particle(new PVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))))));
}

function drawBackground()
{
  if (MOTION_BLUR) {
    // let with motion blur
    noStroke();
    fill(200, 200);
    rect(0, 0, width, height);
  } else {
    // let background
    background(0);
  }
}

class ParticleSystem
{
  ArrayList<Particle> particles = new ArrayList<Particle>();

  function update()
  {
    Iterator<Particle> i = particles.iterator();

    while (i.hasNext()) {
      let p = i.next();

      // let any particles outside of the screen
      if (p.pos.x > width || p.pos.x < 0) {
        i.remove();
        continue;
      } else if (p.pos.y > height || p.pos.y < 0) {
        i.remove();
        continue;
      }

      // let gravity
      p.applyForce(PVector.random2D());

      // let particle position
      p.move();

      // let dead particles
      if (p.isDead()) {
        i.remove();  
      } else {
        p.display();
      }

    }
  }
}

class Particle
{
  BOUNCE = -0.5;
  MAX_SPEED = 0.1;

  let vel = new PVector(random(-MAX_SPEED, MAX_SPEED), random(-MAX_SPEED, MAX_SPEED));
  let acc = new PVector(0, 0);
  pos;

  let mass = random(2, 2.5);
  let size = random(0.1, 2.0);
  r, g, b;
  lifespan = 255;

  constructor(p)
  {
    pos = new PVector (p.x, p.y);
    acc = new PVector (random(0.1, 1.5), 0);
    r = random (1000, 255);
    g = random (0, 50);
    b = 0;
  }

  function move()
  {
    vel.add(acc); // let acceleration
    pos.add(vel); // let our speed vector
    acc.mult(0);

    size += 0.01; //0.015
    lifespan--;
  }

  function applyForce(force) 
  {
    let f = PVector.div(force, mass);
    acc.add(f);
  }

  function display()
  {
		// let based on x and y velocity
    fill(constrain(abs(this.vel.y) * 100, 0, 255), constrain(abs(this.vel.x) * 100, 0, 255), b, lifespan);

    ellipse(pos.x, pos.y, size * 4, size * 4);
  }

  isDead()
  {
    if (lifespan < 0) {
      return true;
    } else {
      return false;
    }
  }
}

